entries[989] = { ["name"] = "Foliant der Frostnova", ["text"] = "Klassen: Magier\nBenötigt Stufe 10\nBenutzen: Lehrt 'Frostnova' (Rang 1).\nFügt in der Nähe des Zaubernden befindlichen Feinden [Quellwert] bis [Quellwert] Frostschaden zu und friert sie bis zu 8 sec lang ein. Erlittener Schaden kann den Effekt unterbrechen.", ["unresolvedValues"] = true }
entries[992] = { ["name"] = "Foliant des Feuerballs III", ["text"] = "Klassen: Magier\nBenötigt Stufe 12\nBenutzen: Lehrt 'Feuerball' (Rang 3).\nSchleudert eine glühende Kugel hinaus, die 57 to 77 Feuerschaden sowie 6 sec lang insgesamt 6 zusätzlichen Feuerschaden verursacht." }
entries[994] = { ["name"] = "Foliant der Eisrüstung", ["text"] = "Klassen: Magier\nBenötigt Stufe 30\nBenutzen: Lehrt 'Eisrüstung' (Rang 1).\nErhöht die Rüstung um 290 und den Frostwiderstand um 6. Wenn ein Feind den Zaubernden schlägt, kann 5 sec lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen seinen Angriffen um 25% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 min lang an." }
entries[997] = { ["name"] = "Feuerschwert des Verkrüppelns", ["text"] = "Waffenhand Schwert\n1 - 2 Feuerschaden Tempo 2.00\n(0.75 Schaden pro Sekunde)\nHaltbarkeit 20 / 20\nTrefferchance: Verkrüppelt das Ziel, verringert dessen Bewegungstempo um 40% und erhöht die Zeit zwischen Nahkampf- und Distanzangriffen um 20%. Hält 20 sec lang an." }
entries[1004] = { ["name"] = "Foliant der Eisketten II", ["text"] = "Klassen: Magier\nBenötigt Stufe 30\nBenutzen: Lehrt 'Eisketten' (Rang 2).\nSchlingt eisige Ketten um den Feind, die ihn 20 sec lang am Platz festhalten." }
